function validate([nums, maxOperations]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 bags.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each bag holds between 1 and 10^9 balls.';
  if (!Number.isInteger(maxOperations) || maxOperations < 1 || maxOperations > 1000000000) return 'maxOperations is between 1 and 10^9.';
  return null;
}

