function minimumSize(nums, maxOperations) {
  let low = 1;
  let high = Math.max(...nums);

  while (low < high) {
    const limit = Math.floor((low + high) / 2);
    let operations = 0;
    for (const balls of nums) {
      operations += Math.floor((balls - 1) / limit);
    }
    if (operations <= maxOperations) {
      high = limit;
    } else {
      low = limit + 1;
    }
  }
  return low;
}

