function minimumSize(nums, maxOperations) {
  // Hand out operations one at a time to the bag whose largest piece is currently biggest.
  // A bag split k times is best cut into k + 1 nearly equal pieces.
  const splits = nums.map(() => 0);
  const piece = i => Math.ceil(nums[i] / (splits[i] + 1));
  for (let used = 0; used < maxOperations; used++) {
    let worst = 0;
    for (let i = 1; i < nums.length; i++) if (piece(i) > piece(worst)) worst = i;
    if (piece(worst) === 1) break;
    splits[worst]++;
  }
  let penalty = 0;
  for (let i = 0; i < nums.length; i++) penalty = Math.max(penalty, piece(i));
  return penalty;
}

