function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const top = rand() < 0.5 ? 1000000000 : 1 + Math.floor(rand() * 100000);
    const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
    const roll = rand();
    const maxOperations = roll < 0.4 ? 1 + Math.floor(rand() * 5000) : roll < 0.8 ? 1 + Math.floor(rand() * 1000000) : 1 + Math.floor(rand() * 1000000000);
    return [nums, maxOperations];
  }
  const n = 1 + Math.floor(rand() * 6);
  const top = rand() < 0.3 ? 5 : 40;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const maxOperations = 1 + Math.floor(rand() * (rand() < 0.5 ? 4 : 25));
  return [nums, maxOperations];
}
